head.script:
scwin.init = function() {
    var jsonData1 = [{
            "col1": "1111",
            "col2": "AAAA"
        },
        {
            "col1": "2222",
            "col2": "BBBB"
        }
    ];
    dataList2.setJSON(jsonData1);
    var jsonData = [{
            "col2": "bbbb1",
            "col3": "cccc1",
            "col4": "dddd1"
        },
        {
            "col2": "bbbb2",
            "col3": "cccc2",
            "col4": "dddd2"
        },
        {
            "col2": "bbbb3",
            "col3": "cccc3",
            "col4": "dddd3"
        },
        {
            "col2": "bbbb4",
            "col3": "cccc4",
            "col4": "dddd4"
        }
    ];
    dataList1.setJSON(jsonData);
    dataList1.setCellData(0, "col1", "AAAA");
    dataList1.setCellData(1, "col1", "AAAA");
    dataList1.setCellData(2, "col1", "BBBB");
    dataList1.setCellData(3, "col1", "BBBB");
}
scwin.fn1 = function(val) {
    return "val=" + val;;
}
scwin.fn2 = function(label) {
    return "label=" + label;
}
scwin.getValue = function(index) {
    if (WebSquare.wUnit.getDomById($p.id + "gridView1_body_tbody").getElementsByTagName("tr").length > 0) {
        var val = WebSquare.wUnit.getJq("#gridView1_body_tbody tr").not(".w2grid_hidedRow")[index].childNodes[0].innerText;
        if (val) {
            return val;
        }
    }
    return "";
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.getValue(4) == 'val=AAAA_label=1111'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.getValue(8) == 'val=BBBB_label=2222'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
	scwin.init()
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 26-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
